export function createSocial(id){
  const event=eventFor({id});
  return {id,round:0,understanding:0,trust:0,log:[`${event.partner}との会話が始まった。`,event.goal],completed:false,result:null,history:[],lastCommand:null};
}
export function getSocialPrompt(b){const event=eventFor(b);if(b.completed)return b.result==='success'?'次に何をするか、互いに分かる会話になった。':'まだ前提を確かめる余地がある。別の話し方も混ぜて、最初から試せる。';const carry=remembered[b.id][b.lastCommand];return `${carry?carry+'\n\n':''}${event.rounds[b.round]?.text||''}`;}
export function getSocialCommands(b){
  const event=eventFor(b);if(b.completed)return [];
  return event.commands.map((c,i)=>({...c,label:event.rounds[b.round].options[i].label,help:`${c.help}${b.lastCommand===c.id?'続けて同じ話し方を使うと、新しい理解は増えにくい。':''}`}));
}
export function resolveSocial(b,commandId){
  const event=eventFor(b);if(b.completed)return structuredClone(b);
  const index=event.commands.findIndex(c=>c.id===commandId);if(index<0)throw new Error('選べない会話コマンドです。');
  if(!Number.isInteger(b.round)||b.round<0||b.round>=event.rounds.length)throw new Error('会話の段階が不正です。');
  const next=structuredClone(b),choice=event.rounds[b.round].options[index],repeated=b.lastCommand===commandId;
  const returning=b.history.some(h=>h.commandId===commandId),varied=b.lastCommand!==null&&!repeated;
  const understanding=Math.max(1,choice.understanding-(repeated?3:0)),trust=Math.max(1,choice.trust-(repeated?2:0));
  next.understanding+=understanding;next.trust+=trust;
  next.log=[`あなた「${choice.label}」`,`${event.partner}：${choice.response}`];
  if(repeated)next.log.push('同じ方向の話が続いた。次は確かめ方を変えると、別の前提が見つかりそうだ。');
  else if(varied){next.trust+=1;next.log.push(returning?'先ほどの話に、別の角度で確かめた内容をつなげられた。':'先ほどの話を踏まえ、別の角度から確かめられた。');}
  next.history.push({round:b.round,commandId,label:choice.label,understanding,trust:trust+(varied?1:0)});
  next.lastCommand=commandId;next.round++;
  next.completed=next.round>=event.rounds.length;
  if(next.completed){
    next.result=next.understanding>=12&&next.trust>=10&&new Set(next.history.map(h=>h.commandId)).size>=2?'success':'retry';
    next.log.push(next.result==='success'?'互いの考えが伝わり、次の約束ができた。':'話したいことは伝えられた。相手の前提も確かめると、さらに進めそうだ。別の組み合わせで何度でも試せる。');
  }
  return next;
}
